import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] fact;
    static long[] invFact;

    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        int n = in.nextInt();
        int m = in.nextInt();
        precompute(n + m);

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = p * (n - i) % MOD * smallInv(n + m - i) % MOD;
            phaseSize += p;
            if (phaseSize >= MOD) phaseSize -= MOD;
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long numPhases = (long) (m + k) % MOD * smallInv(k) % MOD;
            long term = ncr(n, k) * numPhases % MOD * phaseSize % MOD;
            if ((k & 1) == 1) {
                answer += term;
                if (answer >= MOD) answer -= MOD;
            } else {
                answer -= term;
                if (answer < 0) answer += MOD;
            }
        }

        System.out.println(answer);
    }

    static void precompute(int max) {
        fact = new long[max + 1];
        invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[max] = modPow(fact[max], (int) (MOD - 2));
        for (int i = max; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
    }

    static long ncr(int n, int r) {
        if (r < 0 || n < r) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long smallInv(int x) {
        return fact[x - 1] * invFact[x] % MOD;
    }

    static long modPow(long a, int e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
